6: /**
7:  * ApiQueue — Serializes API requests to protect the ESP32 socket pool.
8:  * No concurrent XHR or fetch requests are allowed.
9:  */
10: class ApiQueue {
11:   constructor() {
12:     this.highQueue = [];
13:     this.lowQueue = [];
14:     this.lowDelayMs = 0;
15:     this._delayTimer = null;
16:     this.isProcessing = false;
17:   }
18: 
19:   async enqueue(url, options) {
20:     options = options || {};
21:     return new Promise((resolve, reject) => {
22:       this.highQueue.push({ url, options, resolve, reject });
23:       this._cancelDelay();
24:       this.processNext();
25:     });
26:   }
27: 
28:   /**
29:    * Enqueue a background task with optional delay before the next task.
30:    * @param {Function} taskFn - Function returning a Promise
31:    * @param {number} delayMs - Delay in ms after this task before running the next background task
32:    * @returns {Promise} Resolves/rejects with the task result
33:    */
34:   enqueueTask(taskFn, delayMs) {
35:     return new Promise((resolve, reject) => {
36:       this.lowQueue.push({ taskFn, resolve, reject });
37:       if (delayMs !== undefined) this.lowDelayMs = delayMs;
38:       this.processNext();
39:     });
40:   }
41: 
42:   _cancelDelay() {
43:     if (this._delayTimer) {
44:       clearTimeout(this._delayTimer);
45:       this._delayTimer = null;
46:     }
47:   }
48: 
49:   /**
50:    * Clears all pending background tasks and any active delay timer.
51:    */
52:   clearBackground() {
53:     this.lowQueue = [];
54:     this._cancelDelay();
55:   }
56: 
57:   /**
58:    * Returns the number of pending background tasks.
59:    */
60:   get pendingBackground() {
61:     return this.lowQueue.length;
62:   }
63: 
64:   async processNext() {
65:     if (this.isProcessing) return;
66:     if (this.highQueue.length === 0 && this.lowQueue.length === 0) return;
67: 
68:     this.isProcessing = true;
69: 
70:     var item;
71:     var isHigh = false;
72: 
73:     if (this.highQueue.length > 0) {
74:       item = this.highQueue.shift();
75:       isHigh = true;
76:     } else {
77:       item = this.lowQueue.shift();
78:     }
79: 
80:     try {
81:       if (isHigh) {
82:         var response = await fetch(item.url, item.options);
83: 
84:         // --- 401 Auth Interceptor (WO7) ---
85:         // When auth is enabled and the session is invalid, show the login overlay
86:         // instead of immediately rejecting. The auth module registers an interceptor
87:         // that shows the overlay and the user can retry after logging in.
88:         if (response.status === 401 && _authInterceptor) {
89:           try {
90:             await _authInterceptor();
91:             var retryResponse = await fetch(item.url, item.options);
92:             if (!retryResponse.ok) {
93:               var retryErr = new Error('HTTP ' + retryResponse.status);
94:               retryErr.status = retryResponse.status;
95:               try {
96:                 var rct = retryResponse.headers.get('content-type');
97:                 retryErr.body = (rct && rct.indexOf('application/json') !== -1)
98:                   ? await retryResponse.json()
99:                   : await retryResponse.text();
100:               } catch (e) {
101:                 retryErr.body = null;
102:               }
103:               throw retryErr;
104:             }
105:             response = retryResponse;
106:           } catch (authErr) {
107:             item.reject(authErr);
108:             this.isProcessing = false;
109:             setTimeout(() => this.processNext(), 0);
110:             return;
111:           }
112:         }
113: 
114:         if (!response.ok) {
115:           var err = new Error('HTTP ' + response.status);
116:           err.status = response.status;
117:           try {
118:             var ct = response.headers.get('content-type');
119:             err.body = (ct && ct.indexOf('application/json') !== -1)
120:               ? await response.json()
121:               : await response.text();
122:           } catch (e) {
123:             err.body = null;  // body unreadable/empty — not fatal
124:           }
125:           throw err;
126:         }
127: 
128:         var contentType = response.headers.get('content-type');
129:         if (contentType && contentType.indexOf('application/json') !== -1) {
130:           item.resolve(await response.json());
131:         } else {
132:           item.resolve(await response.text());
133:         }
134:       } else {
135:         var result = await item.taskFn();
136:         item.resolve(result);
137:       }
138:     } catch (error) {
139:       console.error(isHigh ? 'API Error for ' + item.url + ':' : 'Task Error:', error);
140:       item.reject(error);
141:     } finally {
142:       this.isProcessing = false;
143: 
144:       if (isHigh || this.highQueue.length > 0) {
145:         setTimeout(() => this.processNext(), 0);
146:       } else if (this.lowQueue.length > 0 && this.lowDelayMs > 0) {
147:         this._delayTimer = setTimeout(() => this.processNext(), this.lowDelayMs);
148:       } else {
149:         setTimeout(() => this.processNext(), 0);
150:       }
151:     }
152:   }
153: }
