156: var _authInterceptor = null;
157: /**
158:  * @brief Register the 401 auth interceptor callback.
159:  * Called by auth.js on load to wire the login overlay into the API queue.
160:  * @param {Function} showOverlayFn - Function to show the login overlay.
161:  */
162: window.registerAuthInterceptor = function(showOverlayFn) {
163:   _authInterceptor = showOverlayFn;
164: };
