558: void LVGLDisplayModule::reportStatus(const char* message, float progress) {
559:     // Boot runs synchronously in setup(), before the main tick loop pumps
560:     // lv_timer_handler(). LVGL is retained-mode, so updates must be flushed
561:     // explicitly here or boot progress never reaches the panel. Drive the
562:     // designer's boot screen; if the UI failed to load, fall back to the built-in
563:     // FaultScreen (the only code-drawn screen).
564:     if (_bootScreen == nullptr) {
565:         showFault("DISPLAY FAULT", "UI failed to load — reflash");
566:         return;
567:     }
568: 
569:     if (lv_screen_active() != _bootScreen) {
570:         lv_screen_load(_bootScreen);  // immediate — a fade can't advance before the tick loop
571:     }
572: 
573:     auto applyProgress = [](const char* msg, float prog) {
574:         if (prog >= 0.0f) {
575:             int pct = static_cast<int>(prog > 1.0f ? prog : (prog * 100.0f));
576:             pct = std::max(0, std::min(100, pct));
577:             lv_subject_set_int(&sys_boot_progress, pct);
578:         }
579:         if (msg != nullptr) {
580:             lv_subject_copy_string(&sys_boot_status, msg);
581:         }
582:     };
583: 
584:     if (_display == nullptr) {
585:         applyProgress(message, progress);
586:         return;
587:     }
588: 
589:     // Interpolate the bar from the last value to the new one, rendering each
590:     // step, so progress visibly advances (mirrors the U8G2 boot update sequence).
591:     if (progress >= 0.0f && progress > _lastBootProgress + 0.005f) {
592:         const int   kSteps        = 10;
593:         const int   kStepDelayMs  = 12;   // ~120 ms per milestone
594:         const float from          = _lastBootProgress;
595:         const float delta         = progress - from;
596:         for (int i = 1; i <= kSteps; ++i) {
597:             applyProgress(message, from + (delta * (float)i / (float)kSteps));
598:             lv_refr_now(_display);        // force immediate flush — tick loop isn't running yet
599:             delay(kStepDelayMs);
600:         }
601:         _lastBootProgress = progress;
602:     } else {
603:         // No forward progress (e.g. a message-only update): just render once.
604:         applyProgress(message, progress);
605:         lv_refr_now(_display);
606:     }
607: }
