381:     if (item.higherIsBetter) {
382:         // Higher is better (e.g. free heap): low values are bad
383:         if (value <= item.critThreshold) return "CRITICAL";
384:         if (value <= item.warnThreshold) return "LOW";
385:         return "OK";
386:     } else {
387:         // Lower is better (e.g. temperature): high values are bad
388:         if (value >= item.critThreshold) return "CRITICAL";
389:         if (value >= item.warnThreshold) return "HIGH";
390:         return "OK";
391:     }
392: }
393: 
394: lv_color_t DiagCarouselController::evaluateColour(const char* status) const {
395:     if (strcmp(status, "OK") == 0)       return lv_color_hex(COLOR_OK);
396:     if (strcmp(status, "CRITICAL") == 0) return lv_color_hex(COLOR_CRITICAL);
397:     if (strcmp(status, "LOW") == 0)      return lv_color_hex(COLOR_WARN);
398:     if (strcmp(status, "HIGH") == 0)     return lv_color_hex(COLOR_WARN);
399:     return lv_color_hex(COLOR_INFO);  // "—" or unknown
