92:         return false;
93:     }
94: 
95:     // --- Step 4: Spawn background writer task with DRAM stack ---
96:     // MUST use xTaskCreateWithCaps with MALLOC_CAP_INTERNAL because this task
97:     // writes to LittleFS flash. During SPI flash operations the cache is disabled,
98:     // making PSRAM-resident stacks inaccessible (IllegalInstruction on ESP32-S3).
99:     // NOTE: _started is set BEFORE task creation because on dual-core targets
100:     // (ESP32-S3), the new task may be scheduled immediately on the other core.
101:     // If it reads _started == false, the while-loop exits and the writer dies.
102:     _started = true;
