104:         writerLoop,
105:         "AuditWriter",
106:         AUDIT_WRITER_STACK_SIZE,
107:         this,
108:         AUDIT_WRITER_PRIORITY,
109:         &_writerTask,
110:         MALLOC_CAP_INTERNAL | MALLOC_CAP_8BIT
111:     );
